// A minimal stand-in for `effect/Layer`. A Layer builds a new context from the
// current one, registering finalizers in the given scope.
export function effect(service, effect_) {
  if (arguments.length === 1) return (effect_) => effect(service, effect_)
  return { build: async (context, scope) => new Map(context).set(service.key, await effect_.run(context, scope)) }
}

export function succeed(service, value) {
  if (arguments.length === 1) return (value) => succeed(service, value)
  return { build: async (context) => new Map(context).set(service.key, value) }
}

export const provide = (self, that) => ({
  build: async (context, scope) => self.build(await that.build(context, scope), scope)
})

export const mergeAll = (...layers) => ({
  build: async (context, scope) => {
    let merged = new Map(context)
    for (const layer of layers) merged = new Map([...merged, ...(await layer.build(context, scope))])
    return merged
  }
})
